HUSB238_5VCurrentContract Adafruit_HUSB238::get5VContractA() {
  Adafruit_I2CRegister pdRegister = Adafruit_I2CRegister(i2c_dev, HUSB238_PD_STATUS1);
  Adafruit_I2CRegisterBits contractABits = Adafruit_I2CRegisterBits(&pdRegister, 2, 0);  // Bottom two bits (0-1)

  // Read the value from the register
  uint8_t value = contractABits.read();

  // Validate the value to prevent out-of-bounds access
  if (value >= HUSB238_5VCurrentContract_MIN && value <= HUSB238_5VCurrentContract_MAX) {
    return (HUSB238_5VCurrentContract) value;
  } else {
    // Handle the error case, e.g., log the error or return a default value
    // For example, return a default value or throw an exception
    return HUSB238_5VCurrentContract_DEFAULT;
  }
}
